import numpy as np
from PIL import Image
from collections import deque
A=np.load('source_pixels.npz')['rgb']
# Print likely saturated green/yellow pixels bboxes and weighted centroids
for i in range(96):
 im=A[i].astype(int); r,g,b=im[...,0],im[...,1],im[...,2]
 # yellow green saturated candidates, splitting by hue-ish r/g
 masks={
 'yellow':(g>115)&(r>105)&(g>b*1.7)&(r>b*1.7)&(np.abs(r-g)<75),
 'green':(g>75)&(g>r*1.10)&(g>b*1.25)&(r>b*1.15),
 }
 if i%3==0 or i in range(15,31):
  out=[]
  for k,m in masks.items():
   ys,xs=np.where(m)
   if len(xs): out.append(f'{k}:n{len(xs)} bb({xs.min()},{ys.min()})-({xs.max()},{ys.max()}) c({xs.mean():.1f},{ys.mean():.1f})')
  print(i, ' | '.join(out))
